"""Generate the replacement JSX for the news list section."""
import base64, sys

# The replacement content encoded as base64 to avoid escaping issues
b64 = (
    ""
)

decoded = base64.b64decode(b64).decode('utf-8')
with open('scripts/news-replacement.txt', 'w', encoding='utf-8') as f:
    f.write(decoded)
print(f'Written {len(decoded)} chars to scripts/news-replacement.txt')
